def low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def has_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term:
            return
    out.append({'term':term,'support_ids':support})

def make_union(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_and(items):
    if not items:
        return ['no_condition']
    value=items[0]
    i=1
    while i<len(items):
        value=['and_condition',value,items[i]]
        i+=1
    return value

def owner_for_definition(term):
    if isinstance(term,list) and len(term)>1:
        term[1]=['party']
    return term

def recipient_items(text,owner):
    items=[]
    if has_any(text,['employee','staff','personnel']):
        items.append(['employees_of',owner])
    if 'director' in text:
        items.append(['directors_of',owner])
    if has_any(text,['officer','official']):
        items.append(['officers_of',owner])
    if has_any(text,['legal adviser','legal advisor','attorney','legal counsel']):
        items.append(['legal_advisors_of',owner])
    if has_any(text,['financial adviser','financial advisor']):
        items.append(['financial_advisors_of',owner])
    if has_any(text,['professional adviser','professional advisor']):
        items.append(['professional_advisors_of',owner])
    if 'accountant' in text:
        items.append(['accountants_of',owner])
    if 'consultant' in text:
        items.append(['consultants_of',owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of',owner])
    if 'agent' in text:
        items.append(['agents_of',owner])
    if has_any(text,['lender','finance provider']):
        items.append(['lenders_of',owner])
    if not items and 'representative' in text:
        items.append(['representatives_of',owner])
    return items

def disclosure_condition(text,raw):
    conditions=[]
    if has_any(text,['need to know','need-to-know','strict need to know','bona fide need']):
        conditions.append(['need_to_know',raw])
    if has_any(text,['extent necessary','extent absolutely necessary','reasonably necessary','disclosure is necessary','knowledge of the confidential information is reasonably necessary']):
        conditions.append(['extent_necessary',raw])
    if has_any(text,['written confidentiality agreement','written agreement with','signed the mandatory non-disclosure agreement','signed the mandatory nondisclosure agreement','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information as confidential','advise such employees','complies with all the provisions of this agreement','obligated to protect']):
        conditions.append(['confidentiality_bound',raw])
    return make_and(conditions)

def operative_information(text):
    return has_any(text,['confidential information','such confidential information','information it receives from','said information','the same'])

def permission_marker(text):
    return has_any(text,['may disclose','may be disclosed','may share','will disclose information','restrict disclosure','restrict access','disclosed only to','except in confidence to','restrictions in paragraph','restrictions under paragraph'])

def prohibition_marker(text):
    return has_any(text,['shall not disclose','not disclose said information','not to disclose','agrees not to','will not provide confidential information','prohibited from disclosing'])

def actor_for(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    return ['receiving_party']

def parse_definition(raw,uid,statements):
    text=low(raw)
    if not has_any(text,['representative” means','representatives” means','"representative" means','"representatives" means']):
        return
    items=recipient_items(text,['party'])
    if items:
        add_statement(statements,['define_representative',['party'],make_union(items)],[uid])

def parse_disclosure(raw,support,statements):
    text=low(raw)
    if not operative_information(text):
        return
    actor=actor_for(text)
    if permission_marker(text):
        items=recipient_items(text,['receiving_party'])
        if items:
            permission=['permission',actor,['disclose',['confidential_information'],make_union(items)],disclosure_condition(text,raw)]
            add_statement(statements,permission,support)
    if prohibition_marker(text) and has_any(text,['third party','third parties','any other person','any other organization']):
        exceptions=[]
        if has_any(text,['prior written consent','prior written agreement','prior written approval','expressly authorized in writing']):
            exceptions.append(['authorization_exception','source-stated written authorization'])
        if has_any(text,['required to analyze','required to fulfil','required to fulfill','required in the course of service']):
            exceptions.append(['purpose_exception','source-stated required activity'])
        if exceptions:
            ex=['exception_set',exceptions[0]]
            i=1
            while i<len(exceptions):
                ex=['add_exception',ex,exceptions[i]]
                i+=1
        else:
            ex=['no_exceptions']
        add_statement(statements,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],support)
    if has_any(text,['neither it nor its representatives','neither the receiving party nor its representatives']) and has_any(text,['any other person','any other organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        add_statement(statements,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],['no_exceptions']],support)

def information_scope(text):
    items=[['confidential_information']]
    if has_any(text,['copy','copies','reproduction','record copy','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if has_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def trigger_terms(text):
    triggers=[]
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        triggers.append(['relationship_nonformation_deadline'])
    if has_any(text,['termination of service','service terminates','service with']):
        triggers.append(['service_termination'])
    if has_any(text,['termination/expiration of the business relation','termination or expiration of the business relation','termination of the business relationship','termination of the working relationship']):
        triggers.append(['relationship_termination'])
    if has_any(text,['termination of this agreement','expiration of this agreement','expiration or termination of this agreement','termination/expiration of this non-disclosure agreement']):
        triggers.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        triggers.append(['purpose_completion'])
    if has_any(text,['upon request','at any time upon request','promptly upon request','request by','request of','request from']):
        triggers.append(['request_by',['disclosing_party']])
    return unique(triggers)

def trigger_value(triggers):
    if not triggers:
        return None
    value=triggers[0]
    i=1
    while i<len(triggers):
        value=['trigger_alternative',value,triggers[i]]
        i+=1
    return value

def has_return_action(text):
    return has_any(text,['shall return','return to','returned to','promptly return','information will be returned'])

def has_destroy_action(text):
    return has_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text

def add_disposal(raw,support,statements):
    text=low(raw)
    triggers=trigger_terms(text)
    if not triggers:
        return
    do_return=has_return_action(text)
    do_destroy=has_destroy_action(text)
    if not do_return and not do_destroy:
        return
    info=information_scope(text)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    add_statement(statements,['disposal_obligation',actor_for(text),action,trigger_value(triggers),['no_exceptions']],support)

def add_retention(raw,uid,statements):
    text=low(raw)
    info=information_scope(text)
    actor=actor_for(text)
    if has_any(text,['entitled to retain','may retain','may maintain a single copy','permitted to retain']):
        add_statement(statements,['retention_permission',actor,info,['after_disposal'],['retention_condition',raw]],[uid])
    if has_any(text,['without retaining any copies','no copies, electronic or otherwise','no copies or records thereof shall be retained','no copy shall be retained']):
        add_statement(statements,['retention_prohibition',actor,info,['after_disposal']],[uid])
    if has_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy','no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        add_statement(statements,['absolute_retention_prohibition',actor,info],[uid])

def term_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    statements=[]
    source_output=inputs.get('source_output',{})
    if isinstance(source_output,dict):
        for row in source_output.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(statements,row.get('term'),row.get('support_ids',[]))
    texts=[]
    ids=[]
    for span in spans:
        uid=span.get('id')
        raw=span.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw,uid,statements)
        parse_disclosure(raw,[uid],statements)
        add_disposal(raw,[uid],statements)
        add_retention(raw,uid,statements)
    i=0
    while i<len(texts):
        current=low(texts[i])
        if (current.endswith(':') and has_any(current,['may disclose','do not apply to the disclosure','shall be handled as follows'])) or (has_any(current,['return of confidential information','shall be returned','returned to']) and not trigger_terms(current)):
            j=i+1
            while j<len(texts) and j<=i+4:
                combined=' '.join(texts[i:j+1])
                support=ids[i:j+1]
                parse_disclosure(combined,support,statements)
                add_disposal(combined,support,statements)
                j+=1
        triggers=trigger_terms(current)
        if triggers and not has_return_action(current) and not has_destroy_action(current):
            floor=max(0,i-3)
            j=i-1
            while j>=floor:
                previous=low(texts[j])
                if has_return_action(previous) or has_destroy_action(previous):
                    add_disposal(texts[j]+' '+texts[i],[ids[j],ids[i]],statements)
                    break
                j-=1
        i+=1
    definitions=False
    unresolved=[]
    for row in statements:
        if isinstance(row.get('term'),list) and row.get('term') and row.get('term')[0]=='define_representative':
            definitions=True
    if not definitions:
        for row in statements:
            term=row.get('term')
            if term_has(term,'representatives_of'):
                unresolved.append('Representatives membership is used by an operative rule but is not defined in the current source output.')
                break
    return {'statements':statements,'complete':len(unresolved)==0,'unresolved':unresolved}

